const main=document.querySelector('#main'),$=id=>document.getElementById(id);
const s={view:'home',chatId:null,chatTitle:'',conversations:[],chatMessages:[],chatFiles:[],chatInput:'',data:null,doc:null,issue:0,query:'',files:[],fileType:'',folder:'',sort:'recent',draft:null,busy:false};
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

const PAGE_SIZE=10,pages={},pageLists={};
function paged(key,items,row,empty='No items yet.',label='Items'){
 pageLists[key]={items,row,empty,label};
 const total=items.length,count=Math.max(1,Math.ceil(total/PAGE_SIZE));
 const page=pages[key]=Math.max(1,Math.min(pages[key]||1,count)),start=(page-1)*PAGE_SIZE;
 const controls=position=>total>PAGE_SIZE?`<nav class="pagination" aria-label="${e(label)} pages (${position})"><button type="button" data-page="${key}:${page-1}" ${page===1?'disabled':''}>Previous</button><span>Page <strong>${page}</strong> of ${count}</span><button type="button" data-page="${key}:${page+1}" ${page===count?'disabled':''}>Next</button></nav>`:'';
 return `<section id="list-${key}" class="paged-list" aria-label="${e(label)}"><p class="page-summary" tabindex="-1" role="status">${total?`${start+1}-${Math.min(start+PAGE_SIZE,total)} of ${total} ${e(label.toLowerCase())}`:e(empty)}</p>${controls('top')}${items.slice(start,start+PAGE_SIZE).map(row).join('')}${controls('bottom')}</section>`;
}

const dt=v=>new Date(v*1000).toLocaleDateString();
function say(t){$('notice').textContent=t;$('notice').classList.add('show');clearTimeout(say.timer);say.timer=setTimeout(()=>$('notice').classList.remove('show'),8000)}
async function api(path,data){const r=await fetch(path,data===undefined?{cache:'no-store'}:{method:'POST',headers:{'Content-Type':'application/json','X-HARD-CSRF':s.data?.csrf||''},body:JSON.stringify(data)});const j=await r.json();if(!r.ok)throw Error(j.error||'Request failed');return j}
async function refresh(){s.data=await api('/api/state');s.conversations=await api('/api/conversations');s.fileOperations=await api('/api/file-operations')}
async function run(fn){if(s.busy)return;s.busy=true;main.setAttribute('aria-busy','true');const progress=document.createElement('p');progress.className='progress';progress.setAttribute('role','status');progress.textContent='Working… Please wait.';main.prepend(progress);const enabled=[...main.querySelectorAll('button')].filter(b=>!b.disabled);enabled.forEach(b=>b.disabled=true);$('error')?.remove();try{await fn()}catch(err){const el=document.createElement('div');el.id='error';el.className='error';el.setAttribute('role','alert');el.textContent=err.message;main.prepend(el);el.scrollIntoView({block:'nearest'})}finally{s.busy=false;progress.remove();main.removeAttribute('aria-busy');enabled.filter(b=>b.isConnected).forEach(b=>b.disabled=false)}}
async function go(v){if(s.dirty&&!s.submitting&&!window.confirm('Leave this page? Chat and email drafts are kept; other unsaved changes may be lost.'))return;s.dirty=false;s.view=v;if(matchMedia('(max-width:900px)').matches)$('sidebar').open=false;await refresh();if(v==='files'){pages.files=1;s.files=await api('/api/search?q='+encodeURIComponent(s.query));}render();main.focus();window.scrollTo(0,0);pollDelivery()}
async function openDoc(id){s.doc=await api('/api/document/'+id);s.aiReview=await api('/api/ai-review?id='+encodeURIComponent(id));s.aiIndex=0;s.issue=0;s.view='review';render();main.focus()}
const back=()=>'<button class="quiet" data-go="home">← Home</button>';
const field=(label,id,value='',type='text')=>`<label class="field">${label}<input id="${id}" type="${type}" value="${e(value)}" required></label>`;
const check=(id,label)=>`<label class="check"><input id="${id}" type="checkbox" required><span>${label}</span></label>`;
const docRow=d=>`<div class="list-row document-row"><span class="file-symbol" aria-hidden="true">${d.suffix==='.pdf'?'PDF':d.suffix==='.docx'?'W':'TXT'}</span><div class="file-details"><strong>${e(d.name)}</strong><p><span class="review-state ${d.reviewed?'approved':''}">${d.reviewed?'Review approved':'Needs review'}</span><span class="file-date">${dt(d.created)}</span></p></div><button data-doc="${d.id}" aria-label="Open ${e(d.name)}">Open <span aria-hidden="true">→</span></button></div>`;
const icon=(kind)=>`<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${({files:'<path d="M3 7h7l2 2h9v11H3z"/><path d="M3 7V4h7l2 3"/>',documents:'<path d="M6 3h8l4 4v14H6z"/><path d="M14 3v5h4M9 12h6M9 16h4"/>',email:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>'})[kind]}</svg>`;
function profileForm(first=false){const p=s.data.profile||{};return `<form id="profile-form"><label class="field">What should HARD call you?<input id="profile-name" value="${e(p.name||'')}" autocomplete="name" maxlength="100" required></label>${first?'':`<label class="field">Your role (optional)<input id="profile-role" value="${e(p.role||'')}" maxlength="150"></label><label class="field">What would you like HARD to remember? (optional)<textarea id="profile-preferences" maxlength="2000" placeholder="For example, how you prefer to work or the projects you focus on.">${e(p.preferences||'')}</textarea></label><p class="muted">These notes stay on this Windows account. You can edit or clear them here. They are not automatically shared with AI review.</p>`}<button class="primary">${first?'Get started':'Save profile'}</button></form>`}
function welcome(){return `<section class="first-run"><img class="welcome-icon" src="/hard-icon.svg" alt="" width="80" height="80"><p class="eyebrow">HOLLAND AFRICA RESEARCH &amp; DEVELOPMENT</p><h1>Welcome to HARD.</h1><p>A little less admin.<br>More room for your work.</p>${profileForm(true)}<p class="muted">Your name personalises your workspace and new email drafts. You can change it in Settings.</p></section>`}
function pasteChatImage(event){
 const clipboard=event.clipboardData;if(!clipboard)return;
 const files=[...(clipboard.files||[])];
 if(!files.length)for(const item of [...(clipboard.items||[])]){if(item.kind==='file'){const file=item.getAsFile();if(file)files.push(file)}}
 const images=files.filter(f=>f.type.startsWith('image/'));if(!images.length)return;
 event.preventDefault();
 if(s.busy){say('HARD is busy. Paste the image again when the current action finishes.');return}
 if(images.some(f=>!['image/png','image/jpeg','image/webp'].includes(f.type))){say('Paste a PNG, JPEG or WebP image, or save it in one of those formats first.');return}
 const selected=images.map((f,i)=>{const ext={'image/png':'png','image/jpeg':'jpg','image/webp':'webp'}[f.type];return new File([f],'Pasted image '+(s.chatFiles.length+i+1)+'.'+ext,{type:f.type})});
 run(()=>addChatFiles(selected));
}
async function addChatFiles(selected){if(selected.length+s.chatFiles.length>3)throw Error('Attach up to three files.');if(selected.reduce((n,f)=>n+f.size,0)+s.chatFiles.reduce((n,f)=>n+(f.size||0),0)>12*1024*1024)throw Error('Attachments must total 12 MB or less.');const additions=[];for(const f of selected){const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('Cannot read this file.'));reader.readAsDataURL(f)});additions.push({name:f.name,size:f.size,data})}for(const f of additions){try{f.preview=await api('/api/attachment-preview',{name:f.name,data:f.data})}catch(err){f.previewError=err.message}}s.chatFiles.push(...additions);render();$('request')?.focus()}
function chatKeydown(event){
 if(event.key!=='Enter'||event.shiftKey||event.altKey||event.isComposing||event.keyCode===229)return;
 event.preventDefault();
 if(event.repeat||s.busy||!event.currentTarget.value.trim())return;
 const form=event.currentTarget.form,send=form?.querySelector('button[aria-label="Send message"]');
 if(send&&!send.disabled)form.requestSubmit(send);
}
function chatPanel(){const ai=s.data.ai;return `<section class="ask-hard" aria-label="Ask HARD"><div class="chat-toolbar"><h1>${e(s.chatTitle||'New chat')}</h1>${s.chatId?'<div class="chat-options"><button id="chat-options-toggle" type="button" aria-label="Chat options" aria-haspopup="menu" aria-expanded="false" aria-controls="chat-options-menu">•••</button><div id="chat-options-menu" class="chat-options-menu" role="menu" aria-label="Chat options" inert><button id="share-chat" role="menuitem">Share chat <span aria-hidden="true">↗</span></button><button id="rename-chat" role="menuitem">Rename chat</button><button id="delete-chat" class="danger" role="menuitem">Delete chat</button></div></div>':''}</div><div class="chat-log" role="log" aria-label="Conversation" tabindex="0">${s.chatMessages.length?s.chatMessages.map((m,i)=>`<article class="chat-message ${m.role}" id="chat-message-${i}" tabindex="-1"><strong class="message-author">${m.role==='user'?'You':m.role==='error'?'Could not answer':'HARD'}</strong><div class="chat-text ${m.role==='assistant'?'formatted-answer':''}">${m.role==='assistant'?hardFormat(m.content):e(m.content)}</div>${m.actions?.length?`<div class="workflow-actions">${m.actions.map((a,n)=>`<button type="button" data-workflow="${i}:${n}">${e(a.label)}</button>`).join('')}</div>`:''}${m.role==='assistant'&&m.web?.enabled?`<div class="web-sources"><p class="hint">${m.web.sources?.length?'Web sources':'Web enabled · No source links returned. Check current facts independently.'}</p>${(m.web.sources||[]).filter(x=>/^https?:\/\//i.test(x.url)).map(x=>`<a href="${e(x.url)}" target="_blank" rel="noopener noreferrer">${e(x.title)}</a>`).join('')}</div>`:''}${m.role==='error'&&m.retry_turn?`<div class="retry-actions"><button type="button" class="primary" data-retry-answer="${e(m.retry_turn)}">Retry answer</button><button type="button" class="quiet" data-edit-failed="${e(m.retry_turn)}">Edit message</button></div><p class="retry-hint">Your message and attachments are saved.${m.web?.enabled?' Web search stays on for this retry.':''} Retry with ${e(ai?.label||'your selected provider')} · ${e(ai?.model||'selected model')}. Change the connection beside Send if needed.</p>`:''}${m.sources?.length?`<p class="hint">${m.sources.map(f=>e(f.name)+' · '+e(f.mode)).join('<br>')}</p>`:''}${m.attachment_turn?`<button class="quiet" data-restore-attachments="${m.attachment_turn}">Use these attachments</button>`:''}</article>`).join(''):`<div class="chat-welcome"><img src="/hard-icon.svg" alt="" width="52" height="52"><h2>How can I help, ${e(s.data.profile?.name||'there')}?</h2><p>Ask a question or attach something to explore.</p></div>`}</div><form id="ask" class="chat-composer">${s.chatFiles.length?`<div class="chat-files">${s.chatFiles.map((f,i)=>`<div class="attachment-card"><button type="button" class="attachment-preview" data-preview-file="${i}" aria-label="Preview ${e(f.name)}">${f.preview?.images?.length?`<img src="data:image/jpeg;base64,${e(f.preview.images[0].data)}" alt="">`:`<span class="attachment-type" aria-hidden="true">${e(f.name.split('.').pop().toUpperCase())}</span>`}<span>${e(f.name)}</span></button><button type="button" class="attachment-remove" data-chat-remove="${i}" aria-label="Remove ${e(f.name)}">×</button></div>`).join('')}</div>`:''}<label class="sr-only" for="request">Your message</label><textarea id="request" maxlength="8000" required aria-describedby="chat-shortcuts" placeholder="Message HARD…">${e(s.chatInput)}</textarea><div class="composer-controls"><label class="button chat-upload">Attach<input id="chat-upload" type="file" multiple accept=".docx,.pdf,.txt,.png,.jpg,.jpeg,.webp" aria-label="Attach files"></label><button id="voice" type="button" class="quiet" title="${s.data.desktop?'Open Windows voice typing (Windows + H)':'Dictate your message'}">Dictate</button>${ai?.configured?`<label class="provider-choice"><span class="sr-only">AI connection</span><select id="chat-provider" aria-label="AI connection">${(ai.connections||[{id:ai.connection_id||'legacy',name:ai.label+' · '+ai.model}]).map(c=>`<option value="${e(c.id)}" ${c.id===(ai.connection_id||'legacy')?'selected':''}>${e(c.name)}</option>`).join('')}</select></label>${isOpenRouter(ai)?`<button id="choose-model" type="button" class="quiet" title="${e(ai.model)}">Models</button><button id="chat-web" type="button" class="quiet" aria-pressed="${!!s.webSearch}" title="Allow public web search via OpenRouter">Web ${s.webSearch?'on':'off'}</button>`:''}<button class="primary" aria-label="Send message">Send</button>`:'<button class="primary" aria-label="Send message">Send</button><button type="button" class="quiet" data-go="settings">Set up AI</button>'}</div><p id="chat-shortcuts" class="sr-only">Enter to send · Shift+Enter for a new line</p><div class="composer-footnote">${s.webSearch&&isOpenRouter(ai)?'<span class="web-notice">Web on: queries may include conversation details and go to an external search service. Extra charges may apply.</span>':''}<details class="chat-guidance"><summary>Details</summary><div class="chat-help"><p>Chats and attachment copies are saved on this Windows account. Unsent messages and email drafts are saved on this computer.</p><p>Up to 3 files, 12 MB total: Word, PDF, text, PNG, JPEG or WebP. PDFs up to 10 pages include page images; longer PDFs use text. Images require a vision-capable model.</p></div></details></div></form><p class="composer-brand">Holland Africa Research &amp; Development</p></section>`}

function isOpenRouter(ai){return ai?.provider==='openrouter'||ai?.endpoint?.replace(/\/$/,'')==='https://openrouter.ai/api/v1/chat/completions'}
let routerModels=[],modelConnection=null;
function modelDialog(){return `<dialog id="model-dialog" class="share-dialog" aria-labelledby="model-title"><div class="row between"><h2 id="model-title">OpenRouter models</h2><button id="close-models" aria-label="Close models">×</button></div><p class="hint">Choose a model for this connection. No chat content is sent when loading this public list.</p><label class="field">Search models<input id="model-search" type="search" placeholder="Name or model ID"></label><label><input id="model-vision" type="checkbox"> Image-capable only</label><label class="field">Available models<select id="model-list" size="7"></select></label><p id="model-status" class="hint" role="status"></p><div class="row"><button id="use-model" class="primary">Use selected model</button><button id="refresh-models">Refresh list</button></div><p class="hint">Zero token price labels come from the catalog; account limits and other charges may apply. Availability is not a guarantee of access.</p></dialog>`}
function paintModels(){const q=$('model-search').value.toLowerCase(),vision=$('model-vision').checked,rows=routerModels.filter(m=>(m.name+' '+m.id).toLowerCase().includes(q)&&(!vision||m.vision));$('model-list').innerHTML=rows.map(m=>`<option value="${e(m.id)}" ${m.id===s.data.ai.model?'selected':''}>${e(m.name)} · ${e(m.id)}${m.vision?' · Images':''}${m.free?' · Zero token price':''}</option>`).join('');$('use-model').disabled=!rows.length;$('model-status').textContent=rows.length+' matching models.'}
async function loadModels(force=false){$('model-status').textContent='Loading models…';$('use-model').disabled=true;try{const data=await api('/api/openrouter-models'+(force?'?refresh=1':''));routerModels=data.models;paintModels();if(data.stale)$('model-status').textContent+=' Showing the last loaded list; refresh failed.'}catch(err){$('model-status').textContent=err.message}}
async function loadSetupModels(){const status=$('setup-model-status');status.textContent='Loading OpenRouter models…';try{const data=await api('/api/openrouter-models');if(!status.isConnected)return;$('model-suggestions').innerHTML=data.models.map(m=>`<option value="${e(m.id)}">${e(m.name)}${m.vision?' · Images':''}</option>`).join('');status.textContent=data.models.length+' models loaded. Type a name or ID in Model ID to choose.';$('ai-model').focus()}catch(err){if(status.isConnected)status.textContent=err.message}}
function shareDialog(){return `<dialog id="share-dialog" class="share-dialog" aria-labelledby="share-title"><div class="row between"><h2 id="share-title">Share this conversation</h2><button id="close-share" aria-label="Close sharing">×</button></div><p class="share-title">${e(s.chatTitle)}</p><p>Send a readable copy to anyone. Only the saved messages are included; attachment files and account details are excluded.</p><p class="hint">Messages can still contain private information from your documents. Review the conversation before sharing. This exports a copy, not a public link.</p><div class="stack"><button id="download-chat" class="primary">Download readable chat</button><button id="copy-chat">Copy conversation text</button></div><p id="share-status" role="status" class="hint"></p></dialog>`}
function shareText(){return s.chatTitle+'\n\n'+s.chatMessages.map(m=>(m.role==='user'?'You':m.role==='error'?'Notice':'HARD')+'\n'+m.content).join('\n\n')}
function shareHTML(){return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\'; img-src \'none\'; base-uri \'none\'; form-action \'none\'"><title>'+e(s.chatTitle)+'</title><style>body{font:18px/1.65 system-ui,sans-serif;color:#1c3632;background:#f5f6f3;margin:auto;max-width:850px;padding:32px 20px}h1{font-size:1.7em;line-height:1.3}h2,h3,h4{line-height:1.4}article{padding:22px;margin:20px 0;background:white;border:1px solid #c9d4cf;border-radius:16px;overflow-wrap:anywhere}article>strong{color:#356354}pre{white-space:pre-wrap;background:#edf1ed;padding:16px}table{border-collapse:collapse;display:block;overflow:auto}td,th{border:1px solid #c9d4cf;padding:10px}a{color:#185d4b}small{color:#52635e}@media print{body{background:white}article{break-inside:auto}}</style></head><body><small>HARD · Shared conversation</small><h1>'+e(s.chatTitle)+'</h1>'+s.chatMessages.map(m=>'<article><strong>'+(m.role==='user'?'You':m.role==='error'?'Notice':'HARD')+'</strong>'+hardFormat(m.content)+'</article>').join('')+'<small>Conversation snapshot. Attachment files are not included. AI answers may contain mistakes.</small></body></html>'}
function closeChatMenu(focus=false){const b=$('chat-options-toggle'),menu=$('chat-options-menu');if(!menu)return;menu.dataset.open='false';menu.inert=true;b.setAttribute('aria-expanded','false');if(focus)b.focus()}
function bindChatMenu(){const b=$('chat-options-toggle'),menu=$('chat-options-menu');if(!b)return;const open=()=>{menu.dataset.open='true';menu.inert=false;b.setAttribute('aria-expanded','true');setTimeout(()=>{if(menu.isConnected&&menu.dataset.open==='true')menu.querySelector('button').focus()},0)};b.onclick=()=>{if(b.getAttribute('aria-expanded')==='true')closeChatMenu(true);else open()};b.onkeydown=ev=>{if(ev.key==='ArrowDown'){ev.preventDefault();open()}};menu.onkeydown=ev=>{const items=[...menu.querySelectorAll('button')],i=items.indexOf(document.activeElement);if(ev.key==='Escape'){ev.preventDefault();closeChatMenu(true)}else if(['ArrowDown','ArrowUp','Home','End'].includes(ev.key)){ev.preventDefault();items[ev.key==='Home'?0:ev.key==='End'?items.length-1:(i+(ev.key==='ArrowDown'?1:-1)+items.length)%items.length].focus()}};menu.addEventListener('click',()=>closeChatMenu());menu.addEventListener('focusout',()=>setTimeout(()=>{if(menu.isConnected&&!menu.contains(document.activeElement)&&document.activeElement!==b)closeChatMenu()},0))}
document.addEventListener('pointerdown',ev=>{if(!ev.target.closest('.chat-options'))closeChatMenu()});
function home(){return chatPanel()+shareDialog()+modelDialog()+attachmentDialog()}

function chats(){return `${back()}<h1>Chat history</h1><p class="muted">Saved on this Windows account, including attachment copies.</p>${paged('chats',s.conversations,c=>`<div class="list-row"><div><strong>${e(c.title)}</strong><p>${dt(c.updated)}</p></div><button data-chat-open="${c.id}">Open chat</button></div>`,'Your conversations will appear here.','Conversations')}`}
function loadConversation(c){s.chatId=c.id;s.chatTitle=c.title;s.chatMessages=c.messages;s.chatFiles=c.attachments;s.chatInput=''}
async function openChat(id){if(s.chatInput.trim()&&!window.confirm('Discard the message you have not sent?'))return;const c=await api('/api/conversation/'+id);loadConversation(c);await go('home');$('request').focus()}
async function newChat(){if((s.chatInput.trim()||(!s.chatId&&s.chatFiles.length))&&!window.confirm('Start a new chat and discard the unsent message and attachments?'))return;s.chatId=null;s.chatTitle='';s.chatMessages=[];s.chatFiles=[];s.chatInput='';await go('home');$('request').focus()}
function sidebar(){const panel=$('sidebar');if(!matchMedia('(max-width:900px)').matches)panel.open=true;panel.hidden=!s.data.profile;document.body.classList.toggle('has-sidebar',!!s.data.profile);$('sidebar-content').innerHTML=`<div class="sidebar-brand"><img src="/hard-icon.svg" alt="" width="36" height="36"><strong>HARD</strong></div><button id="new-chat" class="primary">+ New chat</button><nav aria-label="Workspace"><button data-side-go="documents">${icon('documents')}Documents</button><button data-side-go="files">${icon('files')}Find a file</button><button data-side-go="email">${icon('email')}Prepare an email</button><button data-side-go="history">Recent work</button></nav><div class="sidebar-history"><h2>Recent chats</h2>${s.conversations.slice(0,8).map(c=>`<button data-side-chat="${c.id}" ${s.chatId===c.id&&s.view==='home'?'aria-current="page"':''} title="${e(c.title)}">${e(c.title)}</button>`).join('')||'<p class="hint">Your chats will appear here.</p>'}<button data-side-go="chats" class="history-all">All chat history →</button></div><p class="sidebar-note">Chats saved on this PC</p>`;const closeMenu=()=>{if(matchMedia('(max-width:900px)').matches)panel.open=false};$('new-chat').onclick=()=>run(async()=>{await newChat();closeMenu()});panel.querySelectorAll('[data-side-go]').forEach(b=>{b.onclick=()=>run(async()=>{await go(b.dataset.sideGo);closeMenu()});if(b.dataset.sideGo===s.view)b.setAttribute('aria-current','page')});panel.querySelectorAll('[data-side-chat]').forEach(b=>b.onclick=()=>run(async()=>{await openChat(b.dataset.sideChat);closeMenu()}))}

function documents(){return `${back()}<h1>Check a document</h1><p>Review or convert a Word document or PDF. Your original stays unchanged.</p><label class="upload">Choose a document<input id="upload" type="file" accept=".docx,.pdf,.txt" aria-label="Choose a document"></label><p class="muted section">Checks cover placeholders, repeated words, comments and tracked changes. Open a document to request an optional AI second opinion.</p>${paged('documents',s.data.documents,docRow,'No documents yet.','Documents')}`}
function aiPanel(){const r=s.aiReview,i=s.aiIndex||0,f=r?.findings[i];return `<section class="panel"><h2>AI second opinion</h2>${r?`<p class="hint">Saved review · ${e(r.provider||'openai')} · ${e(r.model)}</p><p>${e(r.summary)}</p><p class="muted">Suggestions only. Names, dates, amounts and technical claims still need your review.</p>${f?`<p class="progress">Suggestion ${i+1} of ${r.findings.length} · ${e(f.category)}</p><blockquote class="document-text">${e(f.quote)}</blockquote><h3>Check this</h3><p>${e(f.concern)}</p><h3>Suggested next step</h3><p>${e(f.suggestion)}</p><div class="row"><button id="ai-prev" ${i===0?'disabled':''}>Previous suggestion</button><button id="ai-next" ${i===r.findings.length-1?'disabled':''}>Next suggestion</button></div>`:'<p>No concerns identified in this pass. This is not an approval of the document.</p>'}`:`<p>Get suggestions on names, dates, missing information and consistency.</p>${s.data.ai?.configured?`<p>Only this document’s extracted text will be sent to ${e(s.data.ai?.label||'your AI provider')} (${e(s.data.ai?.endpoint||'')}). API usage charges apply. Images and page layout are not included.</p>${check('ai-consent','I am authorised to share this document text with '+e(s.data.ai?.label||'the configured provider')+' for review.')}<button id="ai-review" class="primary">Request AI review</button>`:'<p>AI setup is needed first.</p><button data-go="settings">Set up AI review</button>'}`}</section>`}
function review(){const d=s.doc,items=d.issues;s.issue=Math.min(s.issue,Math.max(0,items.length-1));const item=items[s.issue],left=items.filter(i=>!d.decisions[i.id]).length;return `${back()}<h1>${d.suffix==='.pdf'?'Review the PDF':'Review your document'}</h1><p class="long">${e(d.name)}</p>${d.suffix==='.docx'?'<div class="conversion-panel"><button data-convert-to="pdf">Word to PDF</button><p class="hint">Uses installed desktop Word. Creates a separate PDF copy.</p></div>':d.suffix==='.pdf'?'<div class="conversion-panel"><button data-convert-to="docx">PDF to Word</button><p class="hint">Creates editable text. Original layouts, tables and images are not preserved; scanned pages need OCR.</p></div>':''}<button data-ask-doc="${d.id}">Ask HARD about this document</button><a class="button" href="/document/${d.id}${d.suffix==='.pdf'?'?inline=1':''}" target="_blank" rel="noopener">${d.suffix==='.pdf'?'Open PDF':'Download original copy'}</a>${item?`<section class="panel"><p class="progress">Item ${s.issue+1} of ${items.length} · ${left} left to check</p><h2>${e(item.title)}</h2><p class="long">${e(item.detail)}</p>${item.severity==='block'?'<div class="warning">Resolve this in the original application, then import the revised file.</div>':`<form id="decision"><label class="field">Your review note<textarea id="note" required maxlength="1000" placeholder="Explain what you checked and why this is acceptable.">${e(d.decisions[item.id]||'')}</textarea></label><button class="primary">Save review note</button></form>`}<div class="row section"><button id="previous" ${s.issue===0?'disabled':''}>Previous</button><button id="next" ${s.issue===items.length-1?'disabled':''}>Next item</button></div></section>`:'<div class="success">No issues found by the basic checks. Read the document for accuracy and completeness.</div>'}${aiPanel()}<details><summary>Read extracted text</summary><p class="muted">This does not reproduce the original layout.</p><pre class="document-text">${e(d.content)}</pre></details>${d.suffix!=='.pdf'?`<details><summary>Make a correction</summary><p>Replace one exact occurrence and save a new version. Complex formatting should be edited in Word.</p><form id="replace">${field('Original text','old')}${field('Replacement','new')}<button>Save revised copy</button></form></details>`:''}<section class="section">${d.reviewed?`<div class="success">Review approved.</div>${d.suffix==='.docx'?'<button id="convert" class="primary">Create PDF with Word</button>':d.suffix==='.pdf'?'<button id="use-pdf" class="primary">Prepare an email with this PDF</button>':'<p>Save text as a Word document to convert it to PDF.</p>'}`:`${check('review-confirm','I have read the document'+(d.suffix==='.pdf'?' and opened the PDF to check its pages':'')+' and checked its names, dates and amounts.')}<button id="approve-doc" class="primary" ${left||items.some(i=>i.severity==='block')?'disabled':''}>Approve document review</button>`}</section>`}
function filteredFiles(){let rows=s.files.filter(f=>(!s.fileType||f.name.toLowerCase().endsWith(s.fileType))&&(!s.folder||f.folder_id===s.folder));return rows.sort(s.sort==='name'?(a,b)=>a.name.localeCompare(b.name):s.sort==='oldest'?(a,b)=>a.modified-b.modified:(a,b)=>b.modified-a.modified)}
function files(){return `${back()}${fileUndoPanel()}<h1>Find a file</h1><p class="muted">Search your work folders, then review or organise the right file.</p><form id="search-form">${field('File name or project','search',s.query)}<div class="file-filters"><label class="field">File type<select id="file-type">${[['','All supported files'],['.pdf','PDF'],['.docx','Word'],['.txt','Text']].map(([v,l])=>`<option value="${v}" ${s.fileType===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="field">Work folder<select id="file-folder"><option value="">All work folders</option>${s.data.folders.map(f=>`<option value="${f.id}" ${s.folder===f.id?'selected':''}>${e(f.label)}</option>`).join('')}</select></label><label class="field">Sort by<select id="file-sort">${[['recent','Newest first'],['oldest','Oldest first'],['name','Name A–Z']].map(([v,l])=>`<option value="${v}" ${s.sort===v?'selected':''}>${l}</option>`).join('')}</select></label></div><div class="row"><button class="primary">Search</button><button type="button" id="rescan">Refresh folders</button><button type="button" data-go="settings">Choose folders</button><button type="button" id="find-duplicates">Find duplicates</button></div></form><section class="section">${paged('files',filteredFiles(),f=>`<div class="list-row"><div><strong>${e(f.name)}</strong><p>${e(f.label)} · ${dt(f.modified)}</p><p class="file-path">${e(f.path)}</p></div><div class="row"><button data-file="${f.id}">Open for review</button><details class="file-menu"><summary>More actions</summary><div class="stack"><button data-organise="${f.id}">Organise file</button><button data-rename="${f.id}">Rename file</button>${s.data.desktop?`<button data-reveal="${f.id}">Show in folder</button>`:''}</div></details></div></div>`,'No matching files. Add a work folder in Settings or try a shorter search.','Matches')}</section>`}
function organise(){const f=s.organise;return `${back()}<h1>Add to a project</h1><p class="long">${e(f.name)}</p><p>Choose whether to keep the original or move it. Review the destination before confirming.</p><form id="organise-form"><label class="field">Action<select id="project-mode"><option value="copy">Copy and keep original</option><option value="move">Move into project (same drive)</option></select></label><label class="field">Work folder<select id="project-root" required>${s.data.folders.map(r=>`<option value="${r.id}" ${r.id===f.folder_id?'selected':''}>${e(r.label)} — ${e(r.path)}</option>`).join('')}</select></label><label class="field">Project folder name<input id="project-name" required maxlength="100" placeholder="For example, Accra water assessment"></label><p class="muted">An existing project folder can be used. Files with the same name will never be overwritten.</p><button class="primary">Review file change</button></form><button class="quiet section" data-go="files">Cancel</button>`}
function rename(){const f=s.rename;return `${back()}<p class="eyebrow">FILE MANAGEMENT</p><h1>Rename a file</h1><section class="form-section"><p>Current name</p><strong class="long">${e(f.name)}</strong><p class="file-path">${e(f.path)}</p><form id="rename-form"><label class="field">New file name<input id="rename-name" value="${e(f.name)}" required maxlength="200"></label><p class="hint">Keep the extension. This changes the name in its work folder; imported review copies stay as they are.</p>${check('rename-confirm','I have checked the new name and want to rename this file.')}<button class="primary">Rename file</button><button type="button" class="quiet" data-go="files">Cancel</button></form></section>`}
function duplicates(){const result=s.duplicates;const rows=result.groups.flatMap((g,i)=>g.files.map(f=>({...f,group:i+1,copies:g.files.length})));return `${back()}<p class="eyebrow">FILE MANAGEMENT</p><h1>Duplicate files</h1><p class="muted">Files grouped by identical contents, even when their names differ. Nothing has been deleted.</p><p>${result.groups.length} groups · ${result.skipped} unavailable files skipped</p><button data-go="files">Back to files</button>${paged('duplicates',rows,f=>`<div class="list-row"><div><span class="tag">Group ${f.group} · ${f.copies} copies</span><h3>${e(f.name)}</h3><p class="file-path">${e(f.path)}</p></div>${s.data.desktop?`<button data-reveal="${f.id}">Show in folder</button>`:''}</div>`,'No identical copies found in the indexed files.','Files')}`}
function delivery(){const d=s.delivery,handled=s.deliveryTab==='handled',rows=handled?(d?.handled||[]):(d?.messages||[]);return `${back()}<div class="delivery-heading"><div><p class="eyebrow">EMAIL STATUS</p><h1>Delivery inbox</h1><p class="muted">Review a notice, then mark it as handled.</p></div><button id="refresh-delivery">Check now</button></div><div class="delivery-meta"><span class="connection-badge">${d?.checked_accounts?.length?e(d.checked_accounts.map(p=>p==='gmail'?'Gmail':'Outlook').join(', '))+' · Inbox checked':d?.errors?.length?'Check unavailable':'No recent check'}</span><span>${d?.checked_at?'Checked '+e(new Date(d.checked_at*1000).toLocaleString()):'Connect an email account to start.'}</span></div>${d?.errors?.length?`<p class="warning">Could not check ${e(d.errors.join(', '))}. Try again or check account settings.</p>`:''}<div class="delivery-tabs" role="group" aria-label="Notice status"><button data-delivery-tab="active" aria-pressed="${!handled}">Needs attention <span>${d?.messages?.length||0}</span></button><button data-delivery-tab="handled" aria-pressed="${handled}">Handled <span>${d?.handled?.length||0}</span></button></div>${rows.length?paged(handled?'handledNotices':'delivery',rows,m=>`<article class="delivery-card"><div class="delivery-card-header"><div><p class="eyebrow">${e(m.provider==='gmail'?'Gmail':'Outlook')} · ${e(m.date)}</p><h2>${e(m.subject)}</h2></div><span class="notice-state">${handled?'Handled':'Needs review'}</span></div><div class="delivery-card-actions">${m.provider==='gmail'&&m.id?`<button data-notice-id="${e(m.id)}">Show failure reason</button>`:''}<button class="${handled?'quiet':'primary'}" data-handle-notice="${e(m.key)}" data-handled="${!handled}">${handled?'Move to attention':'Mark as handled'}</button></div><div id="notice-${e(m.id||m.key)}" class="notice-diagnostic"></div></article>`,'','Notices'):`<div class="delivery-empty"><span aria-hidden="true">${handled?'○':'✓'}</span><h2>${handled?'No handled notices yet':d?.errors?.length?'Check incomplete':'Nothing needs your attention'}</h2><p>${handled?'Notices you mark as handled will appear here.':'HARD will show new notices here as it checks your connected inboxes.'}</p></div>`}<div class="delivery-footer"><p>Checks run every five minutes while HARD is open. Handled notices stay in history and stop alerting you; this does not change or delete email. No notice is a guarantee of delivery.</p><button class="quiet" data-go="settings">Email settings</button></div>`}
function paintDelivery(){const box=$('delivery-alert');if(!box)return;const d=s.delivery,uncertain=s.data?.drafts?.filter(x=>['uncertain','failed'].includes(x.status)).length||0,count=d?.messages?.length||0;box.hidden=s.view==='delivery'||!(uncertain||count||d?.errors?.length);box.classList.add('notification-bar');box.innerHTML=`<span class="notification-symbol" aria-hidden="true">!</span><div><strong>${uncertain?'Email sending needs review':count?`${count} delivery notice${count===1?'':'s'} to review`:'Inbox check unavailable'}</strong><span>${uncertain?'Check the send record before trying again.':count?'Review the reason or mark it as handled.':'Check your connection and try again.'}</span></div><button id="delivery-action">${uncertain?'View history':'Review'}</button>`;if($('delivery-action'))$('delivery-action').onclick=()=>run(()=>go(uncertain?'history':'delivery'))}
async function pollDelivery(){if(!s.data?.profile||!Object.values(s.data.accounts).some(a=>a.connected)||s.deliveryBusy)return;s.deliveryBusy=true;try{s.delivery=await api('/api/delivery-status');if(s.view==='delivery')render();else paintDelivery()}catch{s.delivery={messages:[],errors:['connected accounts']};paintDelivery()}finally{s.deliveryBusy=false}}
function contactForm(){return `<form id="contact-form">${field('Full name','contact-name')}${field('Organisation','organization')}${field('Email address','contact-email','','email')}${field('Where did you verify this address?','source')}${check('contact-confirm','I compared this address with the original client request.')}<button>Save verified contact</button></form>`}
function email(){const pdfs=s.data.documents.filter(d=>d.suffix==='.pdf'&&d.reviewed),contacts=s.data.contacts;return `${back()}<p class="eyebrow">EMAIL WORKSPACE</p><h1>Prepare an email</h1><p class="muted">Write it here. Check the details before anything is sent.</p><ol class="steps" aria-label="Email workflow"><li aria-current="step">1. Prepare</li><li>2. Review</li><li>3. Send</li></ol><form id="email-form"><section class="form-section"><div class="section-heading"><span class="step-number">1</span><h2>Who is it for?</h2></div><label class="field">Send from<select id="provider">${['gmail','outlook'].map(p=>`<option value="${p}">${p==='gmail'?'Gmail':'Outlook'} · ${e(s.data.accounts[p].address||'not connected')}</option>`).join('')}</select></label><div class="recipient-choice"><label><input type="radio" name="recipient-mode" value="saved" ${contacts.length?'checked':'disabled'}> Saved contact</label><label><input type="radio" name="recipient-mode" value="new" ${contacts.length?'':'checked'}> Enter an address</label></div><div id="saved-recipient" ${contacts.length?'':'hidden'}><label class="field">Recipient<select id="contact" ${contacts.length?'required':'disabled'}><option value="">Choose a saved contact</option>${contacts.map(c=>`<option value="${c.id}">${e(c.name)} — ${e(c.email)}</option>`).join('')}</select></label><p id="selected-address" class="address"></p></div><div id="new-recipient" ${contacts.length?'hidden':''}><div class="two-fields"><label class="field">Recipient name<input id="recipient-name" autocomplete="off" maxlength="100" ${contacts.length?'disabled':'required'}></label><label class="field">Email address<input id="recipient-email" type="email" autocomplete="off" maxlength="254" ${contacts.length?'disabled':'required'}></label></div><button type="button" id="compare-recipient" class="quiet">Check for similar saved addresses</button><div id="recipient-feedback" role="status"></div><label class="check"><input id="recipient-confirm" type="checkbox" ${contacts.length?'disabled':'required'}><span>I compared this address with the original request and checked every character.</span></label><p class="hint">Used for this email only. Checking the format cannot prove that an address exists.</p></div></section><section class="form-section"><div class="section-heading"><span class="step-number">2</span><h2>Your message</h2></div>${field('Subject','subject')}<label class="field">Message<textarea id="body" required maxlength="20000">Dear colleague,

Please find my proposal attached for your consideration.

Kind regards,
${e(s.data.profile?.name||'')}
Holland Africa Research &amp; Development</textarea></label></section><section class="form-section"><div class="section-heading"><span class="step-number">3</span><h2>Attach your reviewed PDF</h2></div>${!pdfs.length?'<div class="empty"><p>No approved PDFs yet.</p><p>Review a PDF first, then return to prepare your email.</p><button type="button" data-go="documents">Review a document</button></div>':`<label class="field">PDF attachment<select id="attachment" required><option value="">Choose a reviewed PDF</option>${pdfs.map(d=>`<option value="${d.id}" ${s.doc?.id===d.id?'selected':''}>${e(d.name)}</option>`).join('')}</select></label><div id="attachment-preview"></div>${check('visual','I have opened this PDF and checked its pages.')}`}</section><div class="form-actions"><p class="hint">Next, you will review the sender, recipient, message and PDF together.</p><button class="primary" ${!pdfs.length?'disabled':''}>Save draft and review</button></div></form>`}

function draft(){const d=s.draft,p=d.payload,account=s.data.accounts[p.provider];return `${back()}<p class="eyebrow">EMAIL WORKSPACE</p><h1>Check before sending</h1><ol class="steps" aria-label="Email workflow"><li>1. Prepare</li><li aria-current="step">2. Review</li><li>3. Send</li></ol>${d.status!=='draft'?`<div class="warning">${d.status==='failed'?'The provider rejected this email. Check the account, recipient and attachment before preparing a new draft.':d.status==='uncertain'?'Sending result uncertain. Check Sent mail; HARD will not retry.':d.status==='sending'?'Sending in progress. Do not submit again.':'Accepted by the provider. Delivery is not confirmed.'}</div>`:''}<section class="panel"><p>From ${e(account.address||p.provider+' — not connected')}</p><h2>${e(p.contact.name)}</h2><p class="address">${e(p.contact.email)}</p>${!p.contact.verified?'<p class="hint">Address entered for this email. Check every character before sending.</p>':''}<p>${e(p.contact.organization)}</p><strong>${e(p.subject)}</strong><pre>${e(p.body)}</pre><a class="button" href="/document/${p.document_id}?inline=1" target="_blank" rel="noopener">Open attached PDF</a><p class="muted section long">${e(p.attachment_name)}</p></section>${d.status==='failed'?'<button data-go="email">Prepare a new draft</button>':''}${d.status==='draft'?`${account.connected?`<form id="send-form">${check('send-confirm','I approve this sender, recipient, message and attachment.')}<button class="primary">Send this email</button></form>`:'<p>Connect this account in Settings to send from HARD.</p>'}<div class="row section"><a class="button" href="/draft/${d.id}">Download email draft</a><button data-go="email">Prepare a new draft</button></div><p class="muted section">Downloading a draft does not send it. Open it in your email application to finish.</p>`:''}`}
function settings(){return `${back()}<h1>Settings</h1>${maintenancePanel()}<section class="setting-row"><h2>Your profile</h2>${profileForm()}</section><section class="setting-row"><h2>AI connections</h2><p>${s.data.ai?.configured?e(s.data.ai.label)+' · '+e(s.data.ai.model):'Not configured'}</p><p>Document text is shared only when you request a review. Suggestions never edit or approve your document.</p><details><summary>AI privacy</summary><p>Your selected AI provider receives submitted messages, recent conversation context and selected attachments. Switching providers sends context to the new provider on your next message. Retention and training policies depend on your provider and account.</p></details><p class="hint">Saved connections: ${(s.data.ai?.connections||[]).map(c=>e(c.name)).join(', ')||'None yet'}. Choose the active connection beside Send. It is also used for document review.</p><details><summary>Add an AI connection</summary><p>Use an API key from your chosen service. Keys are encrypted for this Windows account. API billing and data retention depend on the provider.</p><form id="ai-setup"><label class="field">Connection name (optional)<input id="ai-name" maxlength="100" placeholder="For example, Gemini work or Claude writing"></label><label class="field">AI provider<select id="ai-provider">${[['openai','OpenAI'],['gemini','Google Gemini'],['anthropic','Anthropic Claude'],['openrouter','OpenRouter'],['compatible','Other OpenAI-compatible service']].map(([v,l])=>`<option value="${v}" ${s.data.ai?.provider===v?'selected':''}>${l}</option>`).join('')}</select></label><button id="setup-models" type="button" ${isOpenRouter(s.data.ai)?'':'hidden'}>Browse OpenRouter models</button><p id="setup-model-status" class="hint"></p><datalist id="model-suggestions"></datalist><label class="field">Model ID<input list="model-suggestions" id="ai-model" required maxlength="150" value="${e(s.data.ai?.model||'')}" placeholder="Exact model ID, for example gemini-3.6-flash"></label><label class="field" id="endpoint-field" ${s.data.ai?.provider==='compatible'?'':'hidden'}>Full chat/completions endpoint<input id="ai-endpoint" type="url" value="${s.data.ai?.provider==='compatible'?e(s.data.ai.endpoint):''}" placeholder="https://your-provider.example/v1/chat/completions"></label><label class="field">API key<input id="ai-key" type="password" autocomplete="off" required></label><p class="hint">Custom providers must support Chat Completions, bearer API keys and JSON output. Saving setup does not verify account access.</p><button>Save connection</button></form></details></section><section class="setting-row"><h2>Reading comfort</h2><label class="field">Reading voice<select id="reading-voice" aria-label="Reading voice"></select></label><label class="field">Reading speed<select id="reading-rate"><option value="0.85">Slower</option><option value="1">Natural</option><option value="1.15">Faster</option></select></label><p class="hint">Read aloud speaks the latest HARD answer. Voice quality depends on voices available on this PC. Local voices are used when available; other voices may use an online speech service.</p><label class="field">Text size<select id="size"><option value="20">Comfortable</option><option value="24">Large</option><option value="28">Extra large</option><option value="40">Double size</option></select></label><p>Desktop Dictate opens Windows voice typing (Windows + H). It requires internet access and a working microphone. Check Windows Settings → Privacy &amp; security → Microphone if access is blocked. Browser dictation depends on browser support.</p></section><section class="setting-row"><h2>Email accounts</h2>${Object.entries(s.data.accounts).map(([p,a])=>`<div class="list-row"><div><strong>${p==='gmail'?'Gmail':'Outlook'}</strong><p>${e(a.address|| (a.configured?'Ready to connect':'Application setup required'))}</p></div>${a.connected?`<button data-disconnect="${p}">Disconnect</button><button data-failures="${p}">Check failure notices</button>`:`<button data-connect="${p}" ${a.configured?'':'disabled'}>Connect</button>`}</div>`).join('')}<details><summary>Application setup</summary><p>Set up the application once, then connect a test account. These credentials stay on this computer, encrypted for your Windows account.</p><h3>Gmail</h3><p>In Google Cloud, enable Gmail API, configure the test audience, and create a Desktop app OAuth client. Download its JSON file.</p><label class="upload">Import Google credentials<input id="google-credentials" type="file" accept=".json,application/json" aria-label="Import Google credentials"></label><h3 class="section">Outlook</h3><p>Register a desktop application in Microsoft Entra with the redirect address http://127.0.0.1:5188/oauth/callback.</p><form id="microsoft-setup">${field('Application (client) ID','microsoft-client')}<button>Save Outlook setup</button></form><p class="muted section">This only configures the application. Connecting an account still requires its owner’s sign-in and consent.</p></details><div id="failure-results"></div></section><section class="setting-row"><h2>Folders to search</h2><p>Choose specific Windows or locally synced OneDrive work folders. Cloud-only files must be available on this device.</p>${paged('folders',s.data.folders,f=>`<div class="list-row"><div><strong>${e(f.label)}</strong><p class="file-path">${e(f.path)}</p></div><button data-remove="${f.id}">Stop including</button></div>`,'No folders added yet.','Folders')}<form id="folder-form">${field('Folder path','folder-path')}${field('Label','folder-label')}<button>Include this folder</button></form></section><section class="setting-row"><h2>Saved contacts</h2>${paged('contacts',s.data.contacts,c=>`<p><strong>${e(c.name)}</strong><br><span class="long">${e(c.email)}</span></p>`,'No verified contacts yet.','Contacts')}<details><summary>Add contact</summary>${contactForm()}</details></section><section class="setting-row"><h2>Feature readiness</h2><p>Word to PDF is available in Documents and requires activated desktop Word. PDF to Word creates an editable text copy locally; it does not reproduce the original layout or perform OCR.</p><p>AI review requires API setup and live testing. Cloud-only OneDrive access is not connected. Delivery checks run while HARD is open and cannot prove receipt.</p></section>`}
function history(){return `${back()}<p class="eyebrow">WORKSPACE HISTORY</p><h1>Your work</h1><p class="muted">Saved emails and recent activity, in one place.</p><button data-go="delivery">Check delivery notices</button>${paged('drafts',s.data.drafts,d=>`<div class="list-row"><div><strong>Email · ${e(d.status)}</strong><p>${dt(d.created)}</p></div><button data-draft="${d.id}">Open record</button></div>`,'No email records yet.','Email records')}<h2 class="section">Recent activity</h2>${paged('events',s.data.events,a=>`<div class="list-row"><div><strong>${e(a.detail)}</strong><p>${dt(a.created)}</p></div></div>`,'No activity yet.','Activities')}`}
function render(){document.body.classList.toggle('chat-mode',s.view==='home'&&!!s.data.profile);sidebar();if(!s.data.profile){main.dataset.view='welcome';main.innerHTML=welcome();bind();return}main.dataset.view=s.view;main.innerHTML=({home,chats,documents,review,files,email,draft,settings,history,organise,rename,duplicates,delivery}[s.view])();if(s.view==='settings'){main.querySelectorAll('section.setting-row').forEach(section=>{const heading=section.querySelector('h2'),details=document.createElement('details'),summary=document.createElement('summary');details.className='setting-row';summary.textContent=heading.textContent;heading.remove();details.append(summary);while(section.firstChild)details.append(section.firstChild);section.replaceWith(details)})}bind();restoreEmail();bindSettingsMotion();setupReadingVoice();paintDelivery();queueRecovery()}
