function preference(){try{const v=localStorage.getItem('hard-text-size');return ['20','24','28','40'].includes(v)?v:'20'}catch{return '20'}}
let speechSession=null;
async function voice(){
 const input=$('request');if(!input)return;
 input.focus();
 if(s.data.desktop){
  const button=$('voice');button.disabled=true;
  try{await api('/api/voice-typing',{});say('Windows voice typing requested. Use its microphone to start or stop. Review the text before sending.');}
  catch(err){say(err.message)}finally{if(button.isConnected)button.disabled=false}
  return;
 }
 if(speechSession){speechSession.stop();return}
 const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;
 if(!Speech){say('This browser does not support dictation. On Windows, click your message and press Windows + H.');return}
 const r=new Speech();speechSession=r;r.lang='en-GB';r.interimResults=false;
 const start=input.selectionStart,end=input.selectionEnd,original=input.value;
 r.onresult=x=>{if($('request')!==input)return;const spoken=x.results[0][0].transcript;if(input.value!==original){say('The message changed while listening. Please dictate again at the new cursor position.');return}const before=original.slice(0,start),after=original.slice(end);const added=(before&&!/\s$/.test(before)?' ':'')+spoken+(after&&!/^\s/.test(after)?' ':'');input.value=(before+added+after).slice(0,8000);input.dispatchEvent(new Event('input',{bubbles:true}));input.focus();input.setSelectionRange(Math.min(start+added.length,8000),Math.min(start+added.length,8000));say('Check the dictated text before sending.')};
 r.onerror=x=>say(({'not-allowed':'Microphone access was denied. Allow microphone access in your browser settings.','audio-capture':'No usable microphone was found. Check your selected microphone in Windows Sound settings.','network':'The browser speech service could not connect. Try Windows voice typing: click your message and press Windows + H.','service-not-allowed':'This browser cannot use its speech service. On Windows, click your message and press Windows + H.','no-speech':'No speech was detected. Check the microphone and try again.','language-not-supported':'This speech service does not support the selected language.'})[x.error]||'Dictation stopped. Try again or use Windows + H.');
 r.onend=()=>{speechSession=null;if($('voice'))$('voice').textContent='Dictate'};
 try{r.start();$('voice').textContent='Stop dictation'}catch{speechSession=null;say('Dictation could not start. On Windows, click your message and press Windows + H.')}
}

let recoveryReady=false,recoveryQueue=Promise.resolve(),recoveryTimer;
function recoverySnapshot(){return {chat:{id:s.chatId,message:s.chatInput,files:s.chatFiles.map(f=>f.document_id?{document_id:f.document_id}:{name:f.name,data:f.data}),web_search:!!s.webSearch},email:s.emailRecovery||null}}
function saveRecovery(){
 if(!recoveryReady)return Promise.resolve();
 clearTimeout(recoveryTimer);const snapshot=recoverySnapshot();
 recoveryQueue=recoveryQueue.catch(()=>{}).then(()=>api('/api/recovery',snapshot));
 return recoveryQueue;
}
function queueRecovery(){if(recoveryReady){clearTimeout(recoveryTimer);recoveryTimer=setTimeout(()=>saveRecovery().catch(()=>say('Draft could not be saved. Keep HARD open and try again.')),400)}}
async function startWorkspace(){
 await refresh();const saved=await api('/api/recovery');
 if(saved.chat){if(saved.chat.id){try{loadConversation(await api('/api/conversation/'+saved.chat.id))}catch{}}
 s.chatInput=saved.chat.message||'';s.chatFiles=saved.chat.files||[];s.webSearch=!!saved.chat.web_search;}
 s.emailRecovery=saved.email||null;recoveryReady=true;await go('home');
 if(s.chatInput||s.emailRecovery)say('Your unfinished work was restored.');
}
function fileUndoPanel(){const ops=(s.fileOperations||[]).filter(o=>o.status==='complete');return ops.length?`<details class="panel"><summary>Undo recent file changes (${ops.length})</summary>${ops.slice(0,10).map(o=>`<div class="list-row"><div><strong>${e(o.kind==='copy'?'Copied to project':o.kind==='move'?'Moved to project':'Renamed file')}</strong><p class="file-path">${e(o.target)}</p></div><button data-undo-file="${e(o.id)}">Undo</button></div>`).join('')}</details>`:''}
function maintenancePanel(){return `<section class="setting-row"><h2>Backups and updates</h2><p>HARD ${e(s.data.version||'development')}</p><button id="backup-workspace">Download workspace backup</button><p class="hint">Includes saved chats, drafts, contacts and imported documents. Backups are not encrypted; store them privately. API keys and account tokens are excluded.</p><p>To restore, close HARD and run Restore-HARD.ps1 from your extracted installation package. The previous workspace is kept for recovery. Existing account connections on this PC are preserved.</p><a class="button" href="https://github.com/Dannyrhay/HARD-AI-Assistant/releases" target="_blank" rel="noopener noreferrer">Check published updates</a><p class="hint">To update, close HARD, extract the new package and run Install-HARD.ps1. Your workspace is kept separately.</p></section>`}
function captureEmail(){if(!$('email-form'))return;const ids=['provider','contact','recipient-name','recipient-email','subject','body','attachment'];s.emailRecovery=Object.fromEntries(ids.map(id=>[id,$(id)?.value||'']));s.emailRecovery.mode=main.querySelector('[name="recipient-mode"]:checked')?.value||'new';queueRecovery()}
function restoreEmail(){if(!$('email-form')||!s.emailRecovery)return;const values=s.emailRecovery;const radio=main.querySelector(`[name="recipient-mode"][value="${values.mode==='saved'?'saved':'new'}"]`);if(radio&&!radio.disabled){radio.checked=true;radio.dispatchEvent(new Event('change',{bubbles:true}))}for(const id of ['provider','contact','recipient-name','recipient-email','subject','body','attachment'])if($(id))$(id).value=values[id]||'';if($('visual'))$('visual').checked=false;if($('recipient-confirm'))$('recipient-confirm').checked=false;}
function bindWorkflows(){
 main.querySelectorAll('[data-workflow]').forEach(b=>b.onclick=()=>run(async()=>{
 const [i,n]=b.dataset.workflow.split(':').map(Number),message=s.chatMessages[i],action=message?.actions?.[n];if(!action)return;
 if(action.kind==='files'){s.query=action.query||'';await go('files')}
 else if(action.kind==='documents'||action.kind==='conversion')await go('documents');
 else if(action.kind==='email'){s.emailRecovery={...(s.emailRecovery||{}),mode:action.recipient?'new':'saved','recipient-email':action.recipient||'',provider:'gmail'};await go('email');}
 else if(action.kind==='duplicates'){s.duplicates=await api('/api/duplicates',{});s.view='duplicates';render()}
 else if(action.kind==='attachment'){const files=await api('/api/chat-attachments/'+message.turn_id),file=files[action.index];if(!file)throw Error('Reattach this document.');if(!/\.(pdf|docx|txt)$/i.test(file.name))throw Error('Choose a PDF, Word or text document for this workflow.');const doc=await api('/api/import',file);await refresh();await openDoc(doc.id)}
 }));
 main.querySelectorAll('[data-undo-file]').forEach(b=>b.onclick=()=>run(async()=>{if(!window.confirm('Undo this file change? A copied file is removed only if it and the original are unchanged.'))return;await api('/api/undo-file',{id:b.dataset.undoFile,confirmed:true});await go('files');say('File change undone.')}));
 if($('backup-workspace'))$('backup-workspace').onclick=()=>run(async()=>{const r=await fetch('/api/backup',{method:'POST',headers:{'Content-Type':'application/json','X-HARD-CSRF':s.data.csrf},body:'{}'});if(!r.ok){const error=await r.json();throw Error(error.error)}const url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download='HARD-backup-'+new Date().toISOString().slice(0,10)+'.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);say('Backup download requested.')});
 main.oninput=event=>{if(event.target.closest('#email-form'))captureEmail()};
 main.onchange=event=>{if(event.target.closest('#email-form'))captureEmail()};
}

document.documentElement.style.fontSize=preference()+'px';$('home').onclick=()=>run(()=>go('home'));$('settings').onclick=()=>run(()=>go('settings'));$('read').onclick=readAnswer;
setInterval(pollDelivery,300000);


function attachmentDialog(){return `<dialog id="attachment-dialog" class="share-dialog attachment-dialog" aria-labelledby="attachment-title"><div class="row between"><h2 id="attachment-title">Attachment preview</h2><button id="close-attachment" aria-label="Close preview">×</button></div><div id="attachment-content"></div></dialog>`}
async function openAttachment(index){
 const f=s.chatFiles[Number(index)];if(!f)return;
 const preview=f.preview||await api('/api/attachment-preview',f.document_id?{document_id:f.document_id}:{name:f.name,data:f.data});f.preview=preview;
 $('attachment-title').textContent=preview.name;
 $('attachment-content').innerHTML=`<p class="hint">${e(preview.note||'Local preview. Nothing is sent to an AI provider.')}</p>${preview.images.map((im,i)=>`<img class="preview-page" src="data:image/jpeg;base64,${e(im.data)}" alt="${e(preview.name)}, preview ${i+1}">`).join('')}${preview.text?`<pre class="preview-text">${e(preview.text)}</pre>`:''}`;
 $('attachment-dialog').showModal();
}
function bindSettingsMotion(){
 if(s.view!=='settings')return;
 main.querySelectorAll('details').forEach(panel=>{
  const summary=panel.querySelector(':scope > summary');if(!summary)return;
  summary.onclick=event=>{
   event.preventDefault();if(panel.dataset.animating)return;
   if(matchMedia('(prefers-reduced-motion: reduce)').matches){panel.open=!panel.open;return}
   const closing=panel.open,start=panel.getBoundingClientRect().height;
   if(!closing)panel.open=true;
   const end=closing?summary.getBoundingClientRect().height+parseFloat(getComputedStyle(panel).paddingTop)+parseFloat(getComputedStyle(panel).paddingBottom)+2:panel.getBoundingClientRect().height;
   panel.dataset.animating='true';panel.style.overflow='hidden';
   const animation=panel.animate([{height:start+'px'},{height:end+'px'}],{duration:210,easing:'cubic-bezier(.2,.7,.2,1)'});
   animation.onfinish=()=>{panel.open=!closing;panel.style.overflow='';delete panel.dataset.animating};
  };
 });
}
function setupReadingVoice(){
 if(!('speechSynthesis' in window))return;
 const select=$('reading-voice');if(select){const voices=speechSynthesis.getVoices();select.innerHTML='<option value="">Automatic (prefer local English)</option>'+voices.map(v=>`<option value="${e(v.voiceURI)}">${e(v.name)} · ${e(v.lang)}${v.localService?' · Local':''}</option>`).join('');select.value=localStorage.getItem('hard-reading-voice')||'';select.onchange=()=>localStorage.setItem('hard-reading-voice',select.value)}
 const rate=$('reading-rate');if(rate){rate.value=localStorage.getItem('hard-reading-rate')||'1';rate.onchange=()=>localStorage.setItem('hard-reading-rate',rate.value)}
}
function readAnswer(){
 if(!('speechSynthesis' in window)){say('Read aloud is unavailable on this PC.');return}
 if(speechSynthesis.speaking||speechSynthesis.pending){speechSynthesis.cancel();$('read').textContent='Read aloud';return}
 const answers=[...main.querySelectorAll('.chat-message.assistant .chat-text')],answer=answers.at(-1);
 if(!answer){say('Open a chat with a HARD answer to read aloud.');return}
 const copy=answer.cloneNode(true);copy.querySelectorAll('pre,code,button').forEach(n=>n.remove());
 const text=copy.innerText||copy.textContent;
 const chunks=text.replace(/\bHARD\b/g,'Hard').match(/[\s\S]{1,700}(?:[.!?]\s|$)|[\s\S]{1,700}/g)||[];
 const voices=speechSynthesis.getVoices(),preferred=localStorage.getItem('hard-reading-voice');
 const voice=voices.find(v=>v.voiceURI===preferred)||voices.find(v=>v.localService&&/^en/i.test(v.lang)&&/natural|zira|aria|jenny/i.test(v.name))||voices.find(v=>v.localService&&/^en/i.test(v.lang))||voices.find(v=>/^en/i.test(v.lang));
 $('read').textContent='Stop reading';
 chunks.forEach((chunk,i)=>{const u=new SpeechSynthesisUtterance(chunk);if(voice)u.voice=voice;u.rate=Number(localStorage.getItem('hard-reading-rate')||1);u.onerror=()=>{$('read').textContent='Read aloud'};if(i===chunks.length-1)u.onend=()=>{$('read').textContent='Read aloud'};speechSynthesis.speak(u)});
}
if('speechSynthesis' in window)speechSynthesis.addEventListener('voiceschanged',setupReadingVoice);

async function retryAnswer(turn){
 const files=s.chatFiles,ai=s.data.ai;
 if(!ai?.configured)throw Error('Choose an AI connection in Settings before retrying.');
 const button=main.querySelector(`[data-retry-answer="${turn}"]`);if(button)button.textContent='Retrying…';
 try{
  const result=await api('/api/chat-retry',{turn_id:turn,conversation_id:s.chatId,confirmed:true,connection_id:ai?.connection_id||'legacy',provider_config:ai?.configured?{provider:ai.provider,model:ai.model,endpoint:ai.endpoint}:null});
  const currentDraft=s.chatInput;
  loadConversation(result.conversation);s.chatInput=currentDraft;s.chatFiles=files;
  await refresh();render();
  const failedIndex=s.chatMessages.findIndex(m=>m.retry_turn===turn);
  if(failedIndex>=0){const el=$('chat-message-'+failedIndex);el?.focus();el?.scrollIntoView({block:'nearest'});say('The retry failed. Your message is still saved.');}
  else{say('Answer received. Your draft is unchanged.');$('request')?.focus();}
 }finally{if(button?.isConnected)button.textContent='Retry answer';}
}
async function editFailedMessage(turn){
 const index=s.chatMessages.findIndex(m=>m.retry_turn===turn),message=s.chatMessages[index-1];if(!message||message.role!=='user')return;
 if(s.chatInput.trim()&&!window.confirm('Replace your unsent draft with this saved message?'))return;
 const before=s.chatInput;const files=await api('/api/chat-attachments/'+turn);if(s.chatInput!==before)throw Error('Your draft changed. Choose Edit message again when ready.');s.chatInput=message.content;s.webSearch=!!message.web?.enabled;s.chatFiles=files;render();$('request').focus();say('Message and attachments restored. Edit, choose a model if needed, then Send.');
}


